import{H as e,V as t,et as n,j as r}from"./chunks/framework.c0x6U8zS.js";var i=JSON.parse(`{"title":"关于本中心","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1786959647000}`),a={name:`about.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="关于本中心" tabindex="-1">关于本中心 <a class="header-anchor" href="#关于本中心" aria-label="Permalink to “关于本中心”">​</a></h1><p>「产品文档中心」是一个<strong>加密的</strong>产品文档站，用于沉淀真实产品的规格、硬件说明、软件功能、接口定义与 FAQ。</p><p>当前已收录：</p><ul><li><strong>AHE01</strong> 益安枕</li><li><strong>AHE02</strong> 益安枕 WIFI 版</li><li><strong>AHE03</strong> 便携枕</li><li><strong>AHE04</strong> 轻音枕</li></ul><p>多款产品共用的说明放在 <a href="/ahs-docs-page/common/">公共文档</a>。</p><h2 id="它是怎么工作的" tabindex="-1">它是怎么工作的 <a class="header-anchor" href="#它是怎么工作的" aria-label="Permalink to “它是怎么工作的”">​</a></h2><ol><li><strong>编写</strong>：每款产品一个文件夹（<code>docs/products/&lt;型号小写&gt;/</code>），内含 <code>index.md</code> 与其它章节；共用内容放 <code>docs/common/</code>。</li><li><strong>构建</strong>：<code>npm run docs:build</code> 把 Markdown 编译成静态 HTML 站点。</li><li><strong>加密</strong>：<code>npm run docs:encrypt</code> 用 <a href="https://github.com/robinmoisson/staticrypt" target="_blank" rel="noreferrer">Staticrypt</a> 对每个 HTML 页面做 <strong>AES 加密</strong>，密码经 PBKDF2 派生密钥，在浏览器端解密。</li><li><strong>分发</strong>：加密产物（默认 <code>encrypted/</code>）放到任意静态服务器、内网或公开托管，内容始终受密码保护。</li></ol><h2 id="安全模型" tabindex="-1">安全模型 <a class="header-anchor" href="#安全模型" aria-label="Permalink to “安全模型”">​</a></h2><ul><li>密码<strong>不会</strong>上传到任何服务器，解密完全在访问者浏览器本地完成。</li><li>每个加密页面自带解密脚本，可独立打开。</li><li>固定的 salt（见 <code>.staticrypt.json</code>）保证「分享链接（share link）」在重新构建后依然有效。</li><li>开启「记住我」后，同一站点内切换页面无需重复输入密码（需通过 HTTP 静态服务器访问，见下方）。</li></ul><h2 id="如何访问" tabindex="-1">如何访问 <a class="header-anchor" href="#如何访问" aria-label="Permalink to “如何访问”">​</a></h2><p>拿到密码后，打开站点首页，输入密码即可。若拿到的是分享链接（带 <code>#staticrypt_pwd=...</code>），点击即可自动解密。</p><h2 id="本地预览加密产物" tabindex="-1">本地预览加密产物 <a class="header-anchor" href="#本地预览加密产物" aria-label="Permalink to “本地预览加密产物”">​</a></h2><blockquote><p>不要直接用 <code>file://</code> 双击打开：浏览器对本地文件的 sessionStorage 隔离会导致多页站点反复要求输入密码。 请用静态服务器：</p></blockquote><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:serve</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # 启动后访问 http://localhost:4173</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><ul><li><strong>忘记密码？</strong> 没有服务端，密码无法找回。请妥善保管，或重新设定密码重新构建。</li><li><strong>明文源码安全吗？</strong> 源码在私有仓库中，访问受仓库权限控制；加密只保护「构建产物」。</li><li><strong>如何更换密码？</strong> 修改 <code>.env</code> 中的 <code>STATICRYPT_PASSWORD</code>，重新执行 <code>npm run docs:build:encrypt</code>。</li><li><strong>如何新增一款产品的文档？</strong> 在 <code>docs/products/</code> 下新建产品文件夹（含 <code>index.md</code> 等章节），并在 <code>docs/.vitepress/products.mjs</code> 的 <code>products</code> 数组中登记型号、简介与颜色。</li></ul>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};